const uint8_t *deskpal_sprite_data(deskpal_sprite_id_t id)
{
    switch (id) {
    case DESKPAL_SPRITE_FOCUS:
        return deskpal_sprite_focus;
    case DESKPAL_SPRITE_BREAK:
        return deskpal_sprite_break;
    case DESKPAL_SPRITE_COMPLETE:
        return deskpal_sprite_complete;
    case DESKPAL_SPRITE_STANDBY:
        return deskpal_sprite_standby;
    case DESKPAL_SPRITE_HUNGRY:
        return deskpal_sprite_hungry;
    case DESKPAL_SPRITE_SICK:
        return deskpal_sprite_sick;
    default:
        return deskpal_sprite_focus;
    }
}

const uint16_t *deskpal_sprite_palette(deskpal_sprite_id_t id)
{
    switch (id) {
    case DESKPAL_SPRITE_HUNGRY:
    case DESKPAL_SPRITE_SICK:
        return deskpal_vitality_palette;
    default:
        return deskpal_palette;
    }
}
